import{bQ as t,aL as e,u as s,G as i}from"./chunks/framework.DaEK0KQB.js";const h=JSON.parse('{"title":"记账心得","description":"","frontmatter":{"title":"记账心得","date":"2025-07-10T11:32:40.000Z","permalink":"/pages/dc2543/","categories":["财务"],"tags":["税务"]},"headers":[],"relativePath":"财务/01.记账心得.md","filePath":"财务/01.记账心得.md","lastUpdated":1787888644000}'),p={name:"财务/01.记账心得.md"};function r(n,a,l,g,o,m){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="记账心得" tabindex="-1">记账心得 <a class="header-anchor" href="#记账心得" aria-label="Permalink to &quot;记账心得&quot;">​</a></h1><h2 id="凭证相关" tabindex="-1">凭证相关 <a class="header-anchor" href="#凭证相关" aria-label="Permalink to &quot;凭证相关&quot;">​</a></h2><p>如果是当月开票，当月结账，就按照这样形式开票</p><p><img src="https://img.kcshen.cn/assets/img/image-20250710113548163.png" alt="image-20250710113548163"></p><p>如果是当月开票，下月入账，就按照这样的形式</p><p>先记录下面的应收账款，然后才是上面的银行存款</p><p><img src="https://img.kcshen.cn/assets/img/image-20250710113859948.png" alt="image-20250710113859948"></p><h3 id="季报" tabindex="-1">季报 <a class="header-anchor" href="#季报" aria-label="Permalink to &quot;季报&quot;">​</a></h3><p>然后就是季报的时候，需要填写如下三个报表</p><p><img src="https://img.kcshen.cn/assets/img/2025/1021-124720-IMG_8594.jpg" alt="IMG_8594"></p><ol><li>首先填写 <strong>增值税</strong> 这个表，然后看到里面可能会有<strong>城市建设税</strong>，如果有的话，就需要去填写如下的凭证</li></ol><p><img src="https://img.kcshen.cn/assets/img/2025/1021-124935-image-20251021124935782.png" alt="image-20251021124935782"></p><ol start="2"><li><p>然后就是看有没有营收，如果有营收的话，还需要填写如下的凭证</p><p><img src="https://img.kcshen.cn/assets/img/2025/1021-125026-image-20251021125026706.png" alt="image-20251021125026706"></p></li><li><p>然后当前月份就可以结账了。</p></li><li><p>开始<strong>企业所得税</strong>的表，需要按照 利润表季报 的数据来进行填写，示例如下</p></li></ol><p><img src="https://img.kcshen.cn/assets/img/2025/1021-125145-image-20251021125145751.png" alt="image-20251021125145751"></p><ol start="5"><li><p>最后就是财务报表，可以平台一键提交。</p></li><li><p>然后是下个月的时候，按照银行的流水，需要记录的凭证</p></li></ol><p><img src="https://img.kcshen.cn/assets/img/2025/1021-125305-image-20251021125305410.png" alt="image-20251021125305410"></p><h2 id="总结如下" tabindex="-1">总结如下： <a class="header-anchor" href="#总结如下" aria-label="Permalink to &quot;总结如下：&quot;">​</a></h2><p><strong>报企业所得税—先把帐上利润表的数据填在税务局的企业所得税表里，如果要交税，就在帐上计提所得税费用，再结转帐，再看资产负债表季度期末余额多少，写在企业所得税的开头资产总额那边。</strong></p>',18)])])}const _=t(p,[["render",r]]);export{h as __pageData,_ as default};
